            ),
            Pasture(
                id = "sample-pasture-4",
                name = "West Lot",
                description = "Holding area near barn",
                sizeAcres = 5.0
            )
        )

        pastures.forEach { insertPasture(it) }
        return pastures.map { it.id }
    }

